from io import StringIO
import re
from django.http import HttpResponseBadRequest

def xpath_query(request):
    '''
    Get the `xpath` value from the GET request,
    get the 'xml' value from the GET request,
    construct and parse the xml payload,
    return the result of the XPath query "/tag[@id={}]" format from the parsed xml
    '''

    # Retrieve values from the request
    xpath_value = request.GET.get('xpath')
    xml_value = request.GET.get('xml')

    # Define a regex pattern for safe XPath expressions
    xpath_pattern = re.compile(r'^/[\w@./-]*$')

    if not xpath_pattern.match(xpath_value):
        return HttpResponseBadRequest("Invalid XPath expression")

    try:
        # Parse the XML content
        xml_content = StringIO(xml_value)
        tree = etree.parse(xml_content)
        root = tree.getroot()

        if not root:
            return HttpResponseBadRequest("Invalid XML format")

        # Execute the XPath query
        result = root.xpath(xpath_value)

        return HttpResponse(str(result))

    except etree.XMLSyntaxError:
        return HttpResponseBadRequest("Invalid XML content")

